# residue8_cats.py: the categories of residue8.py (read by it with exec; cat() and G / R come from there).
# cat(rule, id, census rows or None, label regex, source-line regex, verdict, text, jsgo, check regex)
# A category may also be restricted to files: the line regex is matched against "file\tline text".
# Order matters: the first match wins.

NB = r"Consumer\[any\]\(func\(v any\)|any\(bool\(|any\(int32\(|unbox_\[|\bany\b"

